  1389  int frame_get_lazychunk(blosc2_frame *frame, int nchunk, uint8_t **chunk, bool *needs_free) {
  1390    int32_t header_len;
  1391    int64_t frame_len;
  1392    int64_t nbytes;
  1393    int64_t cbytes;
  1394    int32_t chunksize;
  1395    int32_t nchunks;
  1396
  1397    *chunk = NULL;
  1398    *needs_free = false;
  1399    int ret = get_header_info(frame, &header_len, &frame_len, &nbytes, &cbytes, &chunksize, &nchunks,
  1400                              NULL, NULL, NULL, NULL, NULL);
  1401    if (ret < 0) {
  1402      BLOSC_TRACE_ERROR("Unable to get meta info from frame.");
  1403      return -1;
  1404    }
  1405
  1406    if (nchunk >= nchunks) {
  1407      BLOSC_TRACE_ERROR("nchunk ('%d') exceeds the number of chunks "
  1408                        "('%d') in frame.", nchunk, nchunks);
  1409      return -2;
  1410    }
  1411
  1412    // Get the offset to nchunk
  1413    int64_t offset = get_coffset(frame, header_len, cbytes, nchunk);
  1414
  1415    size_t lazychunk_cbytes = 0;
  1416    if (frame->sdata == NULL) {
  1417      // TODO: make this portable across different endianness
  1418      // Get info for building a lazy chunk
  1419      size_t chunk_nbytes;
  1420      size_t chunk_cbytes;
  1421      size_t chunk_blocksize;
  1422      uint8_t header[BLOSC_MIN_HEADER_LENGTH];
  1423      FILE* fp = fopen(frame->fname, "rb");
  1424      fseek(fp, header_len + offset, SEEK_SET);
  1425      size_t rbytes = fread(header, 1, BLOSC_MIN_HEADER_LENGTH, fp);
  1426      if (rbytes != BLOSC_MIN_HEADER_LENGTH) {
  1427        BLOSC_TRACE_ERROR("Cannot read the header for chunk in the fileframe.");
  1428        return -5;
  1429      }
  1430      blosc_cbuffer_sizes(header, &chunk_nbytes, &chunk_cbytes, &chunk_blocksize);
  1431      size_t nblocks = chunk_nbytes / chunk_blocksize;
  1432      size_t leftover_block = chunk_nbytes % chunk_blocksize;
  1433      nblocks = leftover_block ? nblocks + 1 : nblocks;
  1434      // Allocate space for lazy chunk (cbytes + trailer)
  1435      size_t trailer_len = sizeof(int32_t) + sizeof(int64_t) + nblocks * sizeof(int32_t);
  1436      lazychunk_cbytes = chunk_cbytes + trailer_len;
  1437      *chunk = malloc(lazychunk_cbytes);
  1438      *needs_free = true;
  1439      // Read just the full header and bstarts section too (lazy partial length)
  1440      fseek(fp, header_len + offset, SEEK_SET);
  1441      size_t lazy_partial_len = BLOSC_EXTENDED_HEADER_LENGTH + nblocks * sizeof(int32_t);
  1442      rbytes = fread(*chunk, 1, lazy_partial_len, fp);
  1443      fclose(fp);
  1444      if (rbytes != lazy_partial_len) {
  1445        BLOSC_TRACE_ERROR("Cannot read the (lazy) chunk out of the fileframe.");
  1446        return -6;
  1447      }
  1448
  1449      // Mark chunk as lazy
  1450      uint8_t* blosc2_flags = *chunk + BLOSC2_CHUNK_BLOSC2_FLAGS;
  1451      *blosc2_flags |= 0x08U;
  1452
  1453      // Add the trailer (currently, nchunk + offset + block_csizes)
  1454      *(int32_t*)(*chunk + chunk_cbytes) = nchunk;
  1455      *(int64_t*)(*chunk + chunk_cbytes + sizeof(int32_t)) = header_len + offset;
  1456
  1457      int32_t* block_csizes = malloc(nblocks * sizeof(int32_t));
  1458
  1459      int memcpyed = *(*chunk + BLOSC2_CHUNK_FLAGS) & (uint8_t)BLOSC_MEMCPYED;
  1460      if (memcpyed) {
  1461        // When memcpyed the blocksizes are trivial to compute
  1462        for (int i = 0; i < (int)nblocks; i++) {
  1463          block_csizes[i] = (int)chunk_blocksize;
  1464        }
  1465      }
  1466      else {
  1467        // In regular, compressed chunks, we need to sort the bstarts (they can be out
  1468        // of order because of multi-threading), and get a reverse index too.
  1469        memcpy(block_csizes, *chunk + BLOSC_EXTENDED_HEADER_LENGTH, nblocks * sizeof(int32_t));
  1470        // Helper structure to keep track of original indexes
  1471        struct csize_idx *csize_idx = malloc(nblocks * sizeof(struct csize_idx));
  1472        for (int n = 0; n < (int)nblocks; n++) {
  1473          csize_idx[n].val = block_csizes[n];
  1474          csize_idx[n].idx = n;
  1475        }
  1476        qsort(csize_idx, nblocks, sizeof(struct csize_idx), &sort_offset);
  1477        // Compute the actual csizes
  1478        int idx;
  1479        for (int n = 0; n < (int)nblocks - 1; n++) {
  1480          idx = csize_idx[n].idx;
  1481          block_csizes[idx] = csize_idx[n + 1].val - csize_idx[n].val;
  1482        }
  1483        idx = csize_idx[nblocks - 1].idx;
  1484        block_csizes[idx] = (int)chunk_cbytes - csize_idx[nblocks - 1].val;
  1485        free(csize_idx);
  1486      }
  1487      // Copy the csizes at the end of the trailer
  1488      void *trailer_csizes = *chunk + lazychunk_cbytes - nblocks * sizeof(int32_t);
  1489      memcpy(trailer_csizes, block_csizes, nblocks * sizeof(int32_t));
  1490      free(block_csizes);
